#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    if (!(cin >> n >> x >> pos)) return 0;

    int less = x - 1;          // numbers < x
    int greater = n - x;       // numbers > x

    int l = 0, r = n;
    long long ans = 1;

    while (l < r) {
        int mid = (l + r) / 2;
        if (mid == pos) {
            l = mid + 1;
        } else if (mid < pos) {
            // must place a number < x here
            if (less <= 0) {
                cout << 0;
                return 0;
            }
            ans = ans * less % MOD;
            less--;
            l = mid + 1;
        } else {
            // mid > pos, must place a number > x here
            if (greater <= 0) {
                cout << 0;
                return 0;
            }
            ans = ans * greater % MOD;
            greater--;
            r = mid;
        }
    }

    int remaining = less + greater; // remaining positions to fill
    // multiply by remaining! (for all remaining numbers)
    for (int i = 1; i <= remaining; ++i) {
        ans = ans * i % MOD;
    }

    cout << ans % MOD;
    return 0;
}

