    cin.tie(nullptr);

    int n, x, pos;
    if (!(cin >> n >> x >> pos)) return 0;

    int left = 0, right = n;
    int less = 0, greater = 0;

    while (left < right) {
        int mid = (left + right) / 2;
        if (mid <= pos) {
            if (mid < pos) less++;
            left = mid + 1;
        } else {
            greater++;
            right = mid;
        }
    }

    int smaller = x - 1;
    int larger = n - x;

    if (less > smaller || greater > larger) {
        cout << 0;
        return 0;
    }

    long long ans = 1;

    // choose and permute numbers smaller than x for "less" positions
    for (int i = 0; i < less; ++i) {
        ans = ans * (smaller - i) % MOD;
    }

    // choose and permute numbers greater than x for "greater" positions
    for (int i = 0; i < greater; ++i) {
        ans = ans * (larger - i) % MOD;
    }

    int remaining = n - 1 - less - greater;
    // remaining positions can be filled with remaining numbers in any order
    for (int i = 1; i <= remaining; ++i) {
        ans = ans * i % MOD;
    }

    cout << ans;
    return 0;
}

