#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

long long modmul(long long a, long long b) {
    return (a * b) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, pos;
    if (!(cin >> n >> x >> pos)) return 0;

    int less = x - 1;        // numbers < x
    int greater = n - x;     // numbers > x

    int left = 0, right = n;
    int cntLess = 0, cntGreater = 0;

    while (left < right) {
        int mid = (left + right) / 2;
        if (mid <= pos) {
            if (mid < pos) {
                // we go right, so a[mid] < x
                cntLess++;
            }
            left = mid + 1;
        } else {
            // mid > pos, we go left, so a[mid] > x
            cntGreater++;
            right = mid;
        }
    }

    if (cntLess > less || cntGreater > greater) {
        cout << 0 << '\n';
        return 0;
    }

    long long ans = 1;

    // choose and arrange cntLess numbers from 'less'
    for (int i = 0; i < cntLess; ++i) {
        ans = modmul(ans, less - i);
    }

    // choose and arrange cntGreater numbers from 'greater'
    for (int i = 0; i < cntGreater; ++i) {
        ans = modmul(ans, greater - i);
    }

    // remaining positions can be filled with remaining numbers in any order
    int remaining = n - 1 - cntLess - cntGreater;
    for (int i = 1; i <= remaining; ++i) {
        ans = modmul(ans, i);
    }

    cout << ans << '\n';
    return 0;
}

